diff --git a/internal/hosted/agent/gitstore.go b/internal/hosted/agent/gitstore.go
new file mode 100644
index 0000000..ff89619
--- /dev/null
+++ b/internal/hosted/agent/gitstore.go
@@ -0,0 +1,332 @@
+package agent
+
+import (
+	"bytes"
+	"context"
+	"errors"
+	"fmt"
+	"io"
+	"os"
+	"os/exec"
+	"strconv"
+	"strings"
+	"time"
+	"unicode/utf8"
+)
+
+const (
+	maxBlobBytes     = 2 << 20
+	maxGitOutput     = 512 << 10
+	maxHitsPerFile   = 3
+	maxSnippetBytes  = 300
+	maxListedEntries = 200
+	maxSummaryBytes  = 200
+	defaultGitTime   = 20 * time.Second
+)
+
+// GitRepo backs the agent tools with read-only git queries against a local
+// clone, pinned to Scope.HeadSHA. It never checks out files and never runs
+// anything the repository configures: git can execute repo-chosen commands
+// (textconv filters, fsmonitor hooks) during blame and status-like reads, so
+// those are disabled on every call. The clone is treated as untrusted data.
+type GitRepo struct {
+	Root    string
+	GitPath string
+	Timeout time.Duration
+}
+
+var errNotFound = errors.New("not found at this revision")
+
+// gitError reports a failed git command by name and exit code only: stderr
+// can contain local paths, so it is never surfaced to tools or models.
+type gitError struct {
+	command string
+	code    int
+}
+
+func (e *gitError) Error() string { return "git " + e.command + " failed" }
+
+func (g GitRepo) git(ctx context.Context, limit int, args ...string) (out []byte, truncated bool, err error) {
+	if g.Root == "" {
+		return nil, false, errors.New("git repository root is required")
+	}
+	timeout := g.Timeout
+	if timeout <= 0 {
+		timeout = defaultGitTime
+	}
+	ctx, cancel := context.WithTimeout(ctx, timeout)
+	defer cancel()
+	binary := g.GitPath
+	if binary == "" {
+		binary = "git"
+	}
+	full := append([]string{
+		"-C", g.Root, "--no-pager",
+		"-c", "core.fsmonitor=false",
+		"-c", "core.hooksPath=" + os.DevNull,
+		"-c", "core.quotePath=false",
+	}, args...)
+	cmd := exec.CommandContext(ctx, binary, full...)
+	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0", "GIT_OPTIONAL_LOCKS=0", "GIT_PAGER=cat", "LC_ALL=C")
+	stdout, err := cmd.StdoutPipe()
+	if err != nil {
+		return nil, false, err
+	}
+	var stderr bytes.Buffer
+	cmd.Stderr = &limitedBuffer{buf: &stderr, max: 2 << 10}
+	if err := cmd.Start(); err != nil {
+		return nil, false, fmt.Errorf("start git: %w", err)
+	}
+	data, readErr := io.ReadAll(io.LimitReader(stdout, int64(limit)+1))
+	if len(data) > limit {
+		truncated = true
+		data = data[:limit]
+		cancel()
+	}
+	waitErr := cmd.Wait()
+	if readErr != nil {
+		return nil, false, readErr
+	}
+	if truncated {
+		return data, true, nil
+	}
+	if waitErr != nil {
+		if ctx.Err() != nil {
+			return nil, false, fmt.Errorf("git %s timed out", args[0])
+		}
+		var exit *exec.ExitError
+		code := -1
+		if errors.As(waitErr, &exit) {
+			code = exit.ExitCode()
+		}
+		return nil, false, &gitError{command: args[0], code: code}
+	}
+	return data, false, nil
+}
+
+type limitedBuffer struct {
+	buf *bytes.Buffer
+	max int
+}
+
+func (b *limitedBuffer) Write(p []byte) (int, error) {
+	if room := b.max - b.buf.Len(); room > 0 {
+		b.buf.Write(p[:min(room, len(p))])
+	}
+	return len(p), nil
+}
+
+// blobInfo returns the size of a regular file at the revision.
+func (g GitRepo) blobInfo(ctx context.Context, sha, path string) (int, error) {
+	out, _, err := g.git(ctx, 4<<10, "ls-tree", "-l", sha, "--", path)
+	if err != nil {
+		return 0, err
+	}
+	fields := strings.Fields(strings.SplitN(string(out), "\t", 2)[0])
+	if len(fields) < 4 {
+		return 0, errNotFound
+	}
+	switch {
+	case fields[1] == "tree":
+		return 0, errors.New("path is a directory; use list_files")
+	case fields[0] == "120000":
+		return 0, errors.New("path is a symbolic link")
+	case fields[1] != "blob":
+		return 0, errors.New("path is not a regular file")
+	}
+	size, err := strconv.Atoi(fields[3])
+	if err != nil {
+		return 0, errNotFound
+	}
+	return size, nil
+}
+
+func (g GitRepo) ReadLines(ctx context.Context, scope Scope, path string, start, end int) (string, error) {
+	clean, err := repositoryPath(path)
+	if err != nil {
+		return "", err
+	}
+	size, err := g.blobInfo(ctx, scope.HeadSHA, clean)
+	if err != nil {
+		return "", err
+	}
+	if size > maxBlobBytes {
+		return "", fmt.Errorf("file is %d bytes; files over %d bytes cannot be read, use search_code", size, maxBlobBytes)
+	}
+	data, _, err := g.git(ctx, maxBlobBytes, "show", scope.HeadSHA+":"+clean)
+	if err != nil {
+		return "", err
+	}
+	if bytes.IndexByte(data[:min(len(data), 8000)], 0) >= 0 {
+		return "", errors.New("file is binary")
+	}
+	lines := strings.Split(strings.TrimSuffix(string(data), "\n"), "\n")
+	if len(data) == 0 {
+		lines = nil
+	}
+	if start > len(lines) {
+		return "", fmt.Errorf("file has only %d lines", len(lines))
+	}
+	end = min(end, len(lines))
+	var out strings.Builder
+	fmt.Fprintf(&out, "%s lines %d-%d of %d\n", clean, start, end, len(lines))
+	for i := start; i <= end; i++ {
+		fmt.Fprintf(&out, "%d\t%s\n", i, strings.TrimSuffix(lines[i-1], "\r"))
+	}
+	return out.String(), nil
+}
+
+func (g GitRepo) Search(ctx context.Context, scope Scope, query string, limit int) ([]SearchHit, error) {
+	if strings.ContainsAny(query, "\x00\n\r") {
+		return nil, errors.New("query must be a single line of text")
+	}
+	out, _, err := g.git(ctx, maxGitOutput, "grep", "-n", "-z", "-F", "-I", "--no-color", "-e", query, scope.HeadSHA, "--")
+	if err != nil {
+		// git grep exits 1 when nothing matches; every other failure is real.
+		var failed *gitError
+		if errors.As(err, &failed) && failed.code == 1 {
+			return []SearchHit{}, nil
+		}
+		return nil, err
+	}
+	prefix := scope.HeadSHA + ":"
+	perFile := map[string]int{}
+	hits := []SearchHit{}
+	for _, record := range strings.Split(string(out), "\n") {
+		parts := strings.SplitN(record, "\x00", 3)
+		if len(parts) != 3 || !strings.HasPrefix(parts[0], prefix) {
+			continue
+		}
+		path := strings.TrimPrefix(parts[0], prefix)
+		line, err := strconv.Atoi(parts[1])
+		if err != nil || perFile[path] >= maxHitsPerFile {
+			continue
+		}
+		perFile[path]++
+		hits = append(hits, SearchHit{Path: path, StartLine: line, EndLine: line, Snippet: clipText(parts[2], maxSnippetBytes), Source: "git-grep"})
+		if len(hits) >= limit {
+			break
+		}
+	}
+	return hits, nil
+}
+
+func (g GitRepo) Blame(ctx context.Context, scope Scope, path string, start, end int) ([]BlameLine, error) {
+	clean, err := repositoryPath(path)
+	if err != nil {
+		return nil, err
+	}
+	if _, err := g.blobInfo(ctx, scope.HeadSHA, clean); err != nil {
+		return nil, err
+	}
+	out, _, err := g.git(ctx, maxGitOutput, "blame", "--no-textconv", "--porcelain", "-L", fmt.Sprintf("%d,%d", start, end), scope.HeadSHA, "--", clean)
+	if err != nil {
+		return nil, errors.New("line range is not valid for this file at this revision")
+	}
+	type commitInfo struct{ author, summary string }
+	commits := map[string]*commitInfo{}
+	var lines []BlameLine
+	var current string
+	var finalLine int
+	for _, raw := range strings.Split(string(out), "\n") {
+		switch {
+		case strings.HasPrefix(raw, "\t"):
+			info := commits[current]
+			if info != nil {
+				lines = append(lines, BlameLine{Line: finalLine, Commit: current, Author: info.author, Summary: info.summary})
+			}
+		case isBlameHeader(raw):
+			fields := strings.Fields(raw)
+			current = fields[0]
+			finalLine, _ = strconv.Atoi(fields[2])
+			if commits[current] == nil {
+				commits[current] = &commitInfo{}
+			}
+		case strings.HasPrefix(raw, "author "):
+			commits[current].author = clipText(strings.TrimPrefix(raw, "author "), maxSummaryBytes)
+		case strings.HasPrefix(raw, "summary "):
+			commits[current].summary = clipText(strings.TrimPrefix(raw, "summary "), maxSummaryBytes)
+		}
+	}
+	return lines, nil
+}
+
+func isBlameHeader(line string) bool {
+	fields := strings.Fields(line)
+	if len(fields) < 3 || len(fields[0]) != 40 {
+		return false
+	}
+	for _, r := range fields[0] {
+		if !((r >= '0' && r <= '9') || (r >= 'a' && r <= 'f')) {
+			return false
+		}
+	}
+	_, a := strconv.Atoi(fields[1])
+	_, b := strconv.Atoi(fields[2])
+	return a == nil && b == nil
+}
+
+func (g GitRepo) Log(ctx context.Context, scope Scope, path string, limit int) ([]Commit, error) {
+	clean, err := repositoryPath(path)
+	if err != nil {
+		return nil, err
+	}
+	out, _, err := g.git(ctx, maxGitOutput, "log", "-n", strconv.Itoa(limit), "--format=%H%x1f%an%x1f%aI%x1f%s%x1e", scope.HeadSHA, "--", clean)
+	if err != nil {
+		return nil, err
+	}
+	commits := []Commit{}
+	for _, record := range strings.Split(string(out), "\x1e") {
+		fields := strings.Split(strings.TrimSpace(record), "\x1f")
+		if len(fields) != 4 {
+			continue
+		}
+		commits = append(commits, Commit{SHA: fields[0], Author: clipText(fields[1], maxSummaryBytes), Date: fields[2], Summary: clipText(fields[3], maxSummaryBytes)})
+	}
+	return commits, nil
+}
+
+// ListFiles lists one directory (not recursive) at the revision. Directories
+// end with "/". An empty directory means the repository root.
+func (g GitRepo) ListFiles(ctx context.Context, scope Scope, directory string) ([]string, error) {
+	spec := scope.HeadSHA
+	if directory != "" && directory != "." {
+		clean, err := repositoryPath(directory)
+		if err != nil {
+			return nil, err
+		}
+		spec += ":" + clean
+	}
+	out, _, err := g.git(ctx, maxGitOutput, "ls-tree", "-z", spec)
+	if err != nil {
+		return nil, errors.New("directory not found at this revision")
+	}
+	entries := []string{}
+	for _, record := range strings.Split(string(out), "\x00") {
+		meta, name, ok := strings.Cut(record, "\t")
+		if !ok {
+			continue
+		}
+		if strings.Contains(meta, " tree ") {
+			name += "/"
+		}
+		entries = append(entries, name)
+		if len(entries) >= maxListedEntries {
+			entries = append(entries, "[listing truncated]")
+			break
+		}
+	}
+	return entries, nil
+}
+
+func clipText(value string, limit int) string {
+	value = strings.ToValidUTF8(value, "�")
+	if len(value) <= limit {
+		return value
+	}
+	cut := limit
+	for cut > 0 && !utf8.RuneStart(value[cut]) {
+		cut--
+	}
+	return value[:cut] + "…"
+}

diff --git a/internal/hosted/agent/gitstore_test.go b/internal/hosted/agent/gitstore_test.go
new file mode 100644
index 0000000..8dbe59b
--- /dev/null
+++ b/internal/hosted/agent/gitstore_test.go
@@ -0,0 +1,253 @@
+package agent
+
+import (
+	"context"
+	"os"
+	"os/exec"
+	"path/filepath"
+	"strings"
+	"testing"
+)
+
+type fixture struct {
+	repo   GitRepo
+	scope  Scope
+	first  string
+	marker string
+}
+
+func runGit(t *testing.T, root string, args ...string) string {
+	t.Helper()
+	cmd := exec.Command("git", append([]string{"-C", root, "-c", "user.email=t@example.com", "-c", "user.name=Tess Tester", "-c", "commit.gpgsign=false"}, args...)...)
+	out, err := cmd.CombinedOutput()
+	if err != nil {
+		t.Fatalf("git %s: %v\n%s", strings.Join(args, " "), err, out)
+	}
+	return strings.TrimSpace(string(out))
+}
+
+func write(t *testing.T, root, name, content string) {
+	t.Helper()
+	path := filepath.Join(root, filepath.FromSlash(name))
+	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
+		t.Fatal(err)
+	}
+	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
+		t.Fatal(err)
+	}
+}
+
+// newFixture builds a two-commit repository whose own configuration is
+// hostile: it points textconv and fsmonitor at a script that records a run.
+func newFixture(t *testing.T) fixture {
+	t.Helper()
+	root := t.TempDir()
+	runGit(t, root, "init", "-q")
+	write(t, root, "pkg/a.go", "package pkg\n\nfunc Charge() {}\n")
+	write(t, root, "b.txt", "-x needle\r\nsecond\n")
+	write(t, root, "d:ir/we:ird.txt", "needle in a odd path\n")
+	write(t, root, "bin.dat", "ab\x00cd")
+	write(t, root, "big.txt", strings.Repeat("x", maxBlobBytes+10))
+	write(t, root, ".gitattributes", "*.go diff=evil\n*.txt diff=evil\n")
+	if err := os.Symlink("pkg/a.go", filepath.Join(root, "link.go")); err != nil {
+		t.Skip("symlinks unavailable")
+	}
+	runGit(t, root, "add", "-A")
+	runGit(t, root, "commit", "-qm", "first commit")
+	first := runGit(t, root, "rev-parse", "HEAD")
+	write(t, root, "pkg/a.go", "package pkg\n\nfunc Charge() { refund() }\n")
+	runGit(t, root, "commit", "-qam", "second: call refund")
+	head := runGit(t, root, "rev-parse", "HEAD")
+
+	marker := filepath.Join(t.TempDir(), "marker")
+	script := filepath.Join(t.TempDir(), "evil.sh")
+	if err := os.WriteFile(script, []byte("#!/bin/sh\necho ran >> "+marker+"\ncat \"$1\"\n"), 0o755); err != nil {
+		t.Fatal(err)
+	}
+	runGit(t, root, "config", "diff.evil.textconv", script)
+	runGit(t, root, "config", "core.fsmonitor", script)
+	return fixture{repo: GitRepo{Root: root}, scope: Scope{InstallationID: 1, RepositoryID: 1, HeadSHA: head}, first: first, marker: marker}
+}
+
+func (f fixture) ran() bool {
+	_, err := os.Stat(f.marker)
+	return err == nil
+}
+
+func TestGitRepoNeverRunsRepositoryConfiguredCommands(t *testing.T) {
+	f := newFixture(t)
+	ctx := context.Background()
+	if _, err := f.repo.ReadLines(ctx, f.scope, "pkg/a.go", 1, 3); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := f.repo.Search(ctx, f.scope, "Charge", 10); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := f.repo.Blame(ctx, f.scope, "pkg/a.go", 1, 3); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := f.repo.Log(ctx, f.scope, "pkg/a.go", 5); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := f.repo.ListFiles(ctx, f.scope, ""); err != nil {
+		t.Fatal(err)
+	}
+	if f.ran() {
+		t.Fatal("git executed a command configured by the repository")
+	}
+}
+
+func TestReadLinesNumbersLinesAndStripsCarriageReturns(t *testing.T) {
+	f := newFixture(t)
+	got, err := f.repo.ReadLines(context.Background(), f.scope, "b.txt", 1, 50)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if got != "b.txt lines 1-2 of 2\n1\t-x needle\n2\tsecond\n" {
+		t.Fatalf("read = %q", got)
+	}
+	if _, err := f.repo.ReadLines(context.Background(), f.scope, "b.txt", 3, 4); err == nil || !strings.Contains(err.Error(), "only 2 lines") {
+		t.Fatalf("past end: %v", err)
+	}
+}
+
+func TestReadLinesRefusesUnsafeOrUnreadableFiles(t *testing.T) {
+	f := newFixture(t)
+	for path, want := range map[string]string{
+		"bin.dat":        "binary",
+		"big.txt":        "cannot be read",
+		"link.go":        "symbolic link",
+		"pkg":            "directory",
+		"missing.go":     "not found",
+		"../outside.txt": "repository-relative",
+	} {
+		if _, err := f.repo.ReadLines(context.Background(), f.scope, path, 1, 2); err == nil || !strings.Contains(err.Error(), want) {
+			t.Fatalf("%s: %v, want %q", path, err, want)
+		}
+	}
+}
+
+func TestReadsArePinnedToTheRevision(t *testing.T) {
+	f := newFixture(t)
+	old := f.scope
+	old.HeadSHA = f.first
+	got, err := f.repo.ReadLines(context.Background(), old, "pkg/a.go", 3, 3)
+	if err != nil || !strings.Contains(got, "func Charge() {}") || strings.Contains(got, "refund") {
+		t.Fatalf("old revision = %q %v", got, err)
+	}
+	if _, err := f.repo.ReadLines(context.Background(), Scope{HeadSHA: strings.Repeat("0", 40)}, "pkg/a.go", 1, 1); err == nil {
+		t.Fatal("unknown revision read")
+	}
+}
+
+func TestSearchIsLiteralBoundedAndDistinguishesNoMatchFromFailure(t *testing.T) {
+	f := newFixture(t)
+	hits, err := f.repo.Search(context.Background(), f.scope, "-x needle", 10)
+	if err != nil || len(hits) != 1 || hits[0].Path != "b.txt" || hits[0].StartLine != 1 || hits[0].Source != "git-grep" {
+		t.Fatalf("option-like query: %#v %v", hits, err)
+	}
+	odd, err := f.repo.Search(context.Background(), f.scope, "odd path", 10)
+	if err != nil || len(odd) != 1 || odd[0].Path != "d:ir/we:ird.txt" {
+		t.Fatalf("colon path: %#v %v", odd, err)
+	}
+	if none, err := f.repo.Search(context.Background(), f.scope, "absent-token", 10); err != nil || len(none) != 0 {
+		t.Fatalf("no match: %#v %v", none, err)
+	}
+	if _, err := f.repo.Search(context.Background(), Scope{HeadSHA: strings.Repeat("0", 40)}, "x", 10); err == nil {
+		t.Fatal("a failing grep must not look like an empty result")
+	}
+	if _, err := f.repo.Search(context.Background(), f.scope, "two\nlines", 10); err == nil {
+		t.Fatal("multi-line query accepted")
+	}
+	if regexp, err := f.repo.Search(context.Background(), f.scope, ".*", 10); err != nil || len(regexp) != 0 {
+		t.Fatalf("query must be literal, not a pattern: %#v %v", regexp, err)
+	}
+}
+
+func TestSearchCapsHitsPerFileAndTotal(t *testing.T) {
+	f := newFixture(t)
+	write(t, f.repo.Root, "many.txt", strings.Repeat("token\n", 50))
+	for i := 0; i < 5; i++ {
+		write(t, f.repo.Root, "f"+string(rune('a'+i))+".txt", "token\ntoken\n")
+	}
+	runGit(t, f.repo.Root, "add", "-A")
+	runGit(t, f.repo.Root, "commit", "-qm", "many")
+	scope := f.scope
+	scope.HeadSHA = runGit(t, f.repo.Root, "rev-parse", "HEAD")
+	hits, err := f.repo.Search(context.Background(), scope, "token", 7)
+	if err != nil || len(hits) != 7 {
+		t.Fatalf("hits=%d err=%v", len(hits), err)
+	}
+	perFile := map[string]int{}
+	for _, hit := range hits {
+		if perFile[hit.Path]++; perFile[hit.Path] > maxHitsPerFile {
+			t.Fatalf("%s returned more than %d hits", hit.Path, maxHitsPerFile)
+		}
+	}
+}
+
+func TestBlameAndLogReportCommitsWithoutEmail(t *testing.T) {
+	f := newFixture(t)
+	blame, err := f.repo.Blame(context.Background(), f.scope, "pkg/a.go", 1, 3)
+	if err != nil || len(blame) != 3 {
+		t.Fatalf("blame = %#v %v", blame, err)
+	}
+	if blame[0].Summary != "first commit" || blame[2].Summary != "second: call refund" || blame[2].Author != "Tess Tester" || blame[2].Line != 3 {
+		t.Fatalf("blame lines: %#v", blame)
+	}
+	commits, err := f.repo.Log(context.Background(), f.scope, "pkg/a.go", 10)
+	if err != nil || len(commits) != 2 || commits[0].Summary != "second: call refund" || commits[1].SHA != f.first {
+		t.Fatalf("log = %#v %v", commits, err)
+	}
+	for _, line := range blame {
+		if strings.Contains(line.Author+line.Summary, "example.com") {
+			t.Fatal("author email leaked")
+		}
+	}
+	if clamped, err := f.repo.Blame(context.Background(), f.scope, "pkg/a.go", 1, 99); err != nil || len(clamped) != 3 {
+		t.Fatalf("an end past the file should clamp: %d lines, %v", len(clamped), err)
+	}
+	if _, err := f.repo.Blame(context.Background(), f.scope, "pkg/a.go", 10, 12); err == nil {
+		t.Fatal("a start past the end of the file was accepted")
+	}
+}
+
+func TestListFilesMarksDirectoriesAndRejectsMissingOnes(t *testing.T) {
+	f := newFixture(t)
+	root, err := f.repo.ListFiles(context.Background(), f.scope, "")
+	if err != nil || strings.Join(root, ",") != ".gitattributes,b.txt,big.txt,bin.dat,d:ir/,link.go,pkg/" {
+		t.Fatalf("root = %v %v", root, err)
+	}
+	pkg, err := f.repo.ListFiles(context.Background(), f.scope, "pkg")
+	if err != nil || len(pkg) != 1 || pkg[0] != "a.go" {
+		t.Fatalf("pkg = %v %v", pkg, err)
+	}
+	if _, err := f.repo.ListFiles(context.Background(), f.scope, "nope"); err == nil {
+		t.Fatal("missing directory listed")
+	}
